@Service
class InvoiceArchiver {

    private final Tracer tracer;

    InvoiceArchiver(Tracer tracer) {
        this.tracer = tracer;
    }

    String supportReference() {
        Span span = tracer.currentSpan();
        return span == null ? "none" : span.context().traceId();
    }
}

@Service
class OrderService {

    static final String ORDER_PAID = "ORD-0409";

    void cancel(long orderId) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT,
                "order %d is already paid".formatted(orderId));
        problem.setProperty("code", ORDER_PAID);
        throw new ErrorResponseException(HttpStatus.CONFLICT, problem, null);
    }
}

@EventType("OrderPlaced")
record OrderPlaced(String orderId) {}

@Service
class OrdersService {
    private final EventPublisher publisher;

    OrdersService(EventPublisher publisher) {
        this.publisher = publisher;
    }

    void place(String orderId) {
        publisher.publish("dc.orders", new OrderPlaced(orderId));
    }
}

